export const PRODUCT_NAME = "smarty-code";
export const PRODUCT_MARK = "🤓";
export const brandText = (template: string) => template.replace(/(^|\W)(?:OpenChambers|OpenChamber|smarty-code|OpenCode)(?=$|\W)/g, (_match: string, boundary: string) => boundary + PRODUCT_NAME);
export const brandProductText = (template: string) => template.replace(/([qQ]u|[dDlL])([’'])(OpenChamber|OpenChambers)\b|(^|\W)(?:OpenChambers|OpenChamber|smarty-code)(?=$|\W)/g, (_match: string, prefix: string, _apostrophe: string, _elisionAlias: string, boundary: string) => prefix ? (prefix === 'Qu' ? 'Que ' + PRODUCT_NAME : prefix === 'D' ? 'De ' + PRODUCT_NAME : prefix === 'L' ? 'Le ' + PRODUCT_NAME : prefix.toLowerCase() === 'qu' ? 'que ' + PRODUCT_NAME : prefix.toLowerCase() === 'd' ? 'de ' + PRODUCT_NAME : 'le ' + PRODUCT_NAME) : (boundary ?? '') + PRODUCT_NAME);
